import ast, hashlib, json, subprocess
from pathlib import Path
root=Path('/workspace')
p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
def validate(value,schema,path='"'$'"'):
 types={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}
 if 'type' in schema: assert isinstance(value,types[schema['type']]), (path,'type')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if 'const' in schema: assert value==schema['const'],(path,'const')
 if isinstance(value,dict):
  assert set(schema.get('required',[])) <= set(value),(path,'required')
  if schema.get('additionalProperties') is False:
   assert set(value)<=set(schema.get('properties',{})),(path,'extra')
  for key,item in value.items():
   if key in schema.get('properties',{}): validate(item,schema['properties'][key],path+'.'+key)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,item in enumerate(value):
   if 'items' in schema: validate(item,schema['items'],path+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in allowed
assert set(p['study']['evidence_refs'])<=allowed
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
allowed_imports={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
normalized=[]
configs=[]
for variant in p['variants']:
 file=variant['file']
 assert Path(file).name==file and file.endswith('.py')
 text=(root/file).read_text();tree=ast.parse(text)
 compile(text,file,'exec')
 cfg=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert cfg==variant['config'],(file,'config')
 assert hashlib.sha256(text.encode()).hexdigest()==p['artifact_manifest'][file]
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed_imports for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed_imports
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','compile','__import__','getattr'},(file,n.func.id)
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults={arg.arg:ast.literal_eval(default) for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for key,value in cfg.items():
  expected=defaults[key]
  assert list(expected)==value if isinstance(expected,tuple) else expected==value,(file,key)
 # Normalize only declared config and mode default; all remaining code must match.
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(value=None)
 for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg=='auxiliary_item_mode': default.value='NORMALIZED'
 normalized.append(ast.dump(tree,include_attributes=False))
 configs.append(cfg)
 assert text.index('self.reset_parameters()')<text.index('self.aux_item_layers =')<text.index('self.model_to_device()')
 assert 'values.detach()' in text and 'hidden.detach()' in text
 print('PASS source/config/defaults/imports/hash:',file)
assert len(set(normalized))==1,'Variant code differs beyond config/default mode'
assert {c['auxiliary_item_mode'] for c in configs}=={'private','fixed','tied_primary','tied_joint'}
assert len({json.dumps({k:v for k,v in c.items() if k"'!='"'auxiliary_item_mode'},sort_keys=True) for c in configs})==1
assert all(v['knowledge_id'] in {a['knowledge_id'] for a in p['knowledge_assessments']} for v in r['context']['latest_knowledge_usage']['assessments'])
assert {'unirank-method-infnet','unirank-method-ssr'}<={a['knowledge_id'] for a in p['knowledge_assessments']}
print('PASS study schema, authorized evidence IDs, variant schema, source parity and knowledge coverage')
print('Dynamic checks: NOT RUN (torch absent; no training/installations authorized)')
PY"

